"""Generate the PyInstaller Windows version resource from product_info.py."""

from __future__ import annotations

from pathlib import Path

from product_info import (
    APP_NAME,
    APP_VERSION,
    COMPANY_NAME,
    COPYRIGHT,
    DESCRIPTION,
    EXECUTABLE_NAME,
    version_tuple,
)

TARGET = Path(__file__).with_name("version_info.txt")


def render() -> str:
    version = ", ".join(str(part) for part in version_tuple())
    return f'''# UTF-8
# Generated by generate_version_info.py. Do not edit manually.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers=({version}),
    prodvers=({version}),
    mask=0x3f,
    flags=0x0,
    OS=0x40004,
    fileType=0x1,
    subtype=0x0,
    date=(0, 0)
  ),
  kids=[
    StringFileInfo([
      StringTable(
        '040904B0',
        [
          StringStruct('CompanyName', {COMPANY_NAME!r}),
          StringStruct('FileDescription', {DESCRIPTION!r}),
          StringStruct('FileVersion', {APP_VERSION!r}),
          StringStruct('InternalName', {EXECUTABLE_NAME!r}),
          StringStruct('LegalCopyright', {COPYRIGHT!r}),
          StringStruct('OriginalFilename', {f'{EXECUTABLE_NAME}.exe'!r}),
          StringStruct('ProductName', {APP_NAME!r}),
          StringStruct('ProductVersion', {APP_VERSION!r})
        ]
      )
    ]),
    VarFileInfo([VarStruct('Translation', [0x0409, 1200])])
  ]
)
'''


def main() -> None:
    TARGET.write_text(render(), encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()

